css:
.programsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2433;
    background: linear-gradient(160deg, #f4f6fb 0%, #e9edf6 100%);
    border-radius: 18px;
}

.programsim-container * {
    box-sizing: border-box;
}

.programsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #16203a 0%, #1f2d52 55%, #2a3c6e 100%);
    color: #f3f6fc;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(22, 32, 58, 0.32);
    border-bottom: 3px solid #c8a04b;
}

.programsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.programsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e7c982;
    background: rgba(200, 160, 75, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.programsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d6def0;
}

.programsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a3658;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.programsim-period-counter #currentDay,
.programsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #16203a;
}

.programsim-round-name {
    background: #dde3f1;
    color: #1f2d52;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.programsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5a14;
    background: #fbeed3;
    padding: 4px 12px;
    border-radius: 999px;
}

.programsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.programsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #dde2ee;
    box-shadow: 0 4px 14px rgba(22, 32, 58, 0.06);
    border-top: 4px solid #2a3c6e;
}

.programsim-card-diag { border-top-color: #2f6fb0; }
.programsim-card-transfer { border-top-color: #1d8a6a; }
.programsim-card-impact { border-top-color: #6a4fb0; }
.programsim-card-fee { border-top-color: #c8a04b; }

.programsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #66708a;
}

.programsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #16203a;
}

.programsim-card-diag .programsim-value { color: #2f6fb0; }
.programsim-card-transfer .programsim-value { color: #1d8a6a; }
.programsim-card-impact .programsim-value { color: #6a4fb0; }
.programsim-card-fee .programsim-value { color: #a87d20; }

.programsim-sublabel {
    font-size: 0.76rem;
    color: #7a839a;
    line-height: 1.35;
}

.programsim-fee-secured .programsim-value { color: #1d8a6a; }
.programsim-fee-secured { border-top-color: #1d8a6a; }
.programsim-fee-lost .programsim-value { color: #c0392b; }
.programsim-fee-lost { border-top-color: #c0392b; }

.programsim-budget-over { border-top-color: #c0392b; }
.programsim-budget-over .programsim-value { color: #c0392b; }

.programsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #16203a;
    color: #eef2fb;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 4px solid #c8a04b;
}

.programsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e7c982;
}

.programsim-budget-bar.programsim-budget-breach #budgetDisplay {
    color: #ff9b8a;
}

.programsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c8a04b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(22, 32, 58, 0.05);
}

.programsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.programsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #16203a;
    margin-bottom: 6px;
}

.programsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2f3850;
}

.programsim-briefing-text strong { color: #1d8a6a; }
.programsim-briefing-text em { color: #9a5a14; font-style: italic; }

.programsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #dde2ee;
    box-shadow: 0 4px 14px rgba(22, 32, 58, 0.06);
}

.programsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #16203a;
    border-bottom: 2px solid #e9edf6;
    padding-bottom: 8px;
}

.programsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #28324c;
    margin: 14px 0 6px;
}

.programsim-container select,
.programsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c3cbe0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f8f9fd;
    color: #1c2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.programsim-container select:focus,
.programsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2a3c6e;
    box-shadow: 0 0 0 3px rgba(42, 60, 110, 0.15);
}

.programsim-container select option {
    background-color: #ffffff;
    color: #1c2433;
}

.programsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2a3c6e;
}

.programsim-range-readout,
.programsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2a3c6e;
    margin-top: 4px;
}

.programsim-range-readout span:last-child,
.programsim-alloc-readout span:nth-child(2) {
    color: #1d8a6a;
    font-weight: 800;
}

.programsim-hint {
    font-size: 0.8rem;
    color: #7a839a;
    margin-top: 4px;
    line-height: 1.4;
}

.programsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.programsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f5f7fc;
    border: 1px solid #e2e7f2;
    border-radius: 9px;
    padding: 8px 12px;
}

.programsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #28324c;
}

.programsim-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.programsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.programsim-container .btn-primary {
    background: linear-gradient(135deg, #1f2d52 0%, #2a3c6e 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 16px rgba(31, 45, 82, 0.30);
}

.programsim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.programsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c3cbe0;
    color: #66708a;
}

.programsim-coach {
    background: #16203a;
    color: #eef2fb;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(22, 32, 58, 0.24);
    border-left: 4px solid #c8a04b;
}

.programsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7c982;
    margin-bottom: 8px;
}

.programsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.programsim-coach-body strong { color: #ffd98a; }
.programsim-coach-body em { color: #ffc1ad; font-style: italic; }

.programsim-history,
.programsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #dde2ee;
    box-shadow: 0 4px 14px rgba(22, 32, 58, 0.06);
}

.programsim-history h3,
.programsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #16203a;
}

.programsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #28324c;
}

.programsim-container table#usfHistoryTable th {
    background: #eef1f8;
    color: #16203a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6dcec;
}

.programsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f8;
}

.programsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8f9fd;
}

.programsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .programsim-container {
        padding: 14px;
    }
    .programsim-header h1 {
        font-size: 1.7rem;
    }
    .programsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .programsim-value {
        font-size: 2rem;
    }
    .programsim-clock {
        margin-left: 0;
    }
    .programsim-period-counter {
        font-size: 0.88rem;
    }
    .programsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .programsim-alloc-row {
        flex-wrap: wrap;
    }
    .programsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .programsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) — self-contained, readable on the white modal */
.programsim-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #182338; }
.programsim-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(24,35,56,0.15); margin-bottom: 16px; }
.programsim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #1f6f6a; }
.programsim-cm-score-max { font-size: 18px; font-weight: 600; color: #45597a; margin-left: 2px; }
.programsim-cm-grade { font-size: 18px; font-weight: 700; color: #182338; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.programsim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.programsim-cm-yes { background: rgba(31,111,106,0.16); color: #185a55; }
.programsim-cm-no { background: rgba(176,51,37,0.12); color: #b03325; }
.programsim-cm-warn { background: rgba(180,110,20,0.16); color: #8a5410; }
.programsim-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.programsim-cm-metric { flex: 1 1 120px; background: #eef1f6; border: 1px solid rgba(24,35,56,0.10); border-radius: 10px; padding: 12px 14px; text-align: center; }
.programsim-cm-mv { display: block; font-size: 22px; font-weight: 800; color: #182338; }
.programsim-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #45597a; margin-top: 2px; }
.programsim-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #45597a; margin-bottom: 8px; }
.programsim-cm-insights { margin: 0; padding-left: 20px; }
.programsim-cm-insights li { font-size: 14px; line-height: 1.5; color: #23324a; margin-bottom: 8px; }

