(function() {
    'use strict';

    class ProgramAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Designing the Program`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Whitfield / Brackenmoor).
            this.BUDGET_CAP = 1.80;          // GBP 1.8M client ceiling, in millions
            this.AT_RISK_FEE = 360;          // GBP 360k contingent (20% of fee), in thousands
            this.PER_HEAD_CAP = 10;          // ~GBP 10k/head, in thousands
            this.FLAGSHIP_PRICE = 13.5;      // GBP 13.5k flagship price/head, in thousands
            this.IMPACT_FEE_FLOOR = 60;      // impact credibility needed to secure the fee
            this.TARGET_COMPOSITE = 68;      // award-worthy mandate threshold

            // Concept truths.
            this.TRUE_ROOT = `structural`;          // not the CEO's "skills" framing
            this.TRUE_METRIC = `leading`;           // attributable leading behavioural indicator
            this.ATTRIBUTABLE_METRICS = [`leading`];
            this.CREDIBLE_ATTRIBUTION = [`control`, `prepost`];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    diag: 18,
                    transfer: 12,
                    impact: 14,
                    budgetUsed: 0,
                    budgetBreach: false,
                    feeSecured: false,
                    feeLost: false,
                    overpromised: false,
                    diagHistory: [18],
                    transferHistory: [12],
                    impactHistory: [14],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    root: `structural`,
                    addressable: 55,
                    candour: 60,
                    reach: `all_blend`,
                    transferAlloc: 45,
                    workshopAlloc: 35,
                    digitalAlloc: 20,
                    spend: 1.70,
                    levels: `behaviour_results`,
                    metric: `leading`,
                    attribution: `control`,
                    baseline: 120,
                    roi: `attributed`,
                    boardCandour: `honest`,
                    competitor: `evidence`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const root = document.getElementById(`rootInput`);
                const addr = document.getElementById(`addressableInput`);
                const cand = document.getElementById(`candourInput`);
                if (root) decisions.root = root.value;
                if (addr) decisions.addressable = parseInt(addr.value, 10);
                if (cand) decisions.candour = parseInt(cand.value, 10);
                if (!Number.isFinite(decisions.addressable) || decisions.addressable < 0 || decisions.addressable > 100) {
                    warn(`warn_addressable_range`); return false;
                }
                if (!Number.isFinite(decisions.candour) || decisions.candour < 0 || decisions.candour > 100) {
                    warn(`warn_candour_range`); return false;
                }
            } else if (round === 2) {
                const reach = document.getElementById(`reachInput`);
                const sp = document.getElementById(`spendInput`);
                if (reach) decisions.reach = reach.value;
                const tA = document.getElementById(`transferAllocInput`);
                const wA = document.getElementById(`workshopAllocInput`);
                const dA = document.getElementById(`digitalAllocInput`);
                if (tA) decisions.transferAlloc = parseFloat(tA.value);
                if (wA) decisions.workshopAlloc = parseFloat(wA.value);
                if (dA) decisions.digitalAlloc = parseFloat(dA.value);
                if (sp) decisions.spend = parseFloat(sp.value);
                const parts = [decisions.transferAlloc, decisions.workshopAlloc, decisions.digitalAlloc];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(decisions.transferAlloc + decisions.workshopAlloc + decisions.digitalAlloc);
                if (total !== 100) {
                    warn(`warn_alloc_total`); return false;
                }
                if (!Number.isFinite(decisions.spend) || decisions.spend < 0) {
                    warn(`warn_spend_negative`); return false;
                }
            } else if (round === 3) {
                const lv = document.getElementById(`levelsInput`);
                const me = document.getElementById(`metricInput`);
                const at = document.getElementById(`attributionInput`);
                const bl = document.getElementById(`baselineInput`);
                if (lv) decisions.levels = lv.value;
                if (me) decisions.metric = me.value;
                if (at) decisions.attribution = at.value;
                if (bl) decisions.baseline = parseFloat(bl.value);
                if (!Number.isFinite(decisions.baseline) || decisions.baseline < 0) {
                    warn(`warn_baseline_negative`); return false;
                }
            } else if (round === 4) {
                const roi = document.getElementById(`roiInput`);
                const bc = document.getElementById(`boardCandourInput`);
                const cp = document.getElementById(`competitorInput`);
                const cv = document.getElementById(`convictionInput`);
                if (roi) decisions.roi = roi.value;
                if (bc) decisions.boardCandour = bc.value;
                if (cp) decisions.competitor = cp.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Three meters: diagnostic rigour (D), transfer strength (T), impact credibility (I).
            let diagDelta = 0, transferDelta = 0, impactDelta = 0;
            let spend = 0; // GBP millions committed this round
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the real gap, not the CEO's presenting symptom (Common Error 1).
                if (d.root === this.TRUE_ROOT) {
                    diagDelta += 22; impactDelta += 2; coachKey = `coach_r1_structural`;
                } else if (d.root === `skills`) {
                    diagDelta -= 10; coachKey = `coach_r1_skills`;
                } else if (d.root === `motivation`) {
                    diagDelta -= 14; coachKey = `coach_r1_motivation`;
                } else {
                    diagDelta -= 12; coachKey = `coach_r1_selection`;
                }

                // Addressable share: a realistic split (40–65%) is the disciplined answer.
                if (d.addressable >= 40 && d.addressable <= 65) {
                    diagDelta += 10;
                    if (d.root === this.TRUE_ROOT) coachKey = `coach_r1_diag_sharp`;
                } else if (d.addressable > 80) {
                    diagDelta -= 6; coachKey = `coach_r1_overclaim`;
                } else if (d.addressable < 25) {
                    diagDelta -= 4; coachKey = `coach_r1_underclaim`;
                }

                // Candour: telling the CEO what training cannot fix.
                if (d.candour >= 60) { diagDelta += 8; impactDelta += 4; }
                else if (d.candour <= 25) { diagDelta -= 8; coachKey = `coach_r1_lowcandour`; }

                summaryKey = (d.root === this.TRUE_ROOT && d.addressable >= 40 && d.addressable <= 65) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Design within the cap, trading reach against depth, building for transfer (Errors 2 & 4).
                switch (d.reach) {
                    case `all_blend`: transferDelta += 14; impactDelta += 4; coachKey = `coach_r2_blend`; break;
                    case `few_deep`: transferDelta += 8; impactDelta += 2; coachKey = `coach_r2_fewdeep`; break;
                    case `all_deep`: transferDelta += 6; coachKey = `coach_r2_alldeep`; break;
                    case `all_light`: transferDelta -= 8; impactDelta -= 4; coachKey = `coach_r2_light`; break;
                }

                // Modality mix: transfer mechanisms produce behaviour change, not contact hours.
                const tA = d.transferAlloc, wA = d.workshopAlloc, dA = d.digitalAlloc;
                const transferLed = tA >= 40 && tA >= wA && tA >= dA;
                if (transferLed) {
                    transferDelta += 18;
                    if (d.reach === `all_blend`) coachKey = `coach_r2_transferled`;
                } else if (wA >= 50) {
                    transferDelta -= 6; coachKey = `coach_r2_workshop`;
                } else if (dA >= 50) {
                    transferDelta -= 4; coachKey = `coach_r2_digital`;
                } else {
                    transferDelta += 4;
                }

                // Budget discipline: spend above GBP 1.8M cannot be contracted (Error 2).
                spend = d.spend;
                if (d.spend > this.BUDGET_CAP + 0.001) {
                    transferDelta -= 10; impactDelta -= 6; ds.budgetBreach = true; coachKey = `coach_r2_overbudget`;
                } else if (d.spend < 1.0) {
                    transferDelta -= 6; coachKey = `coach_r2_underspend`;
                }

                summaryKey = (transferLed && d.spend <= this.BUDGET_CAP + 0.001 && d.reach !== `all_light`) ? `sum_r2_good` : (ds.budgetBreach ? `sum_r2_overbudget` : `sum_r2_weak`);
            } else if (round === 3) {
                // Build the measurement model: reach behaviour & results, stake an attributable metric (Errors 3 & 5).
                switch (d.levels) {
                    case `behaviour_results`: impactDelta += 18; transferDelta += 4; coachKey = `coach_r3_behres`; break;
                    case `learning`: impactDelta -= 8; coachKey = `coach_r3_learning`; break;
                    case `reaction`: impactDelta -= 12; coachKey = `coach_r3_reaction`; break;
                }

                // Which metric the GBP 360k is staked on — attributability is the whole game.
                switch (d.metric) {
                    case `leading`: impactDelta += 14; coachKey = (d.levels === `behaviour_results`) ? `coach_r3_metric_sharp` : coachKey; break;
                    case `overruns`: impactDelta -= 10; coachKey = `coach_r3_overruns`; break;
                    case `safety`: impactDelta -= 8; coachKey = `coach_r3_safety`; break;
                    case `satisfaction`: impactDelta -= 12; coachKey = `coach_r3_satisfaction`; break;
                }

                // Attribution method — credible isolation vs hopeful correlation.
                switch (d.attribution) {
                    case `control`: impactDelta += 12; transferDelta += 2; break;
                    case `prepost`: impactDelta += 4; break;
                    case `correlation`: impactDelta -= 8; coachKey = `coach_r3_correlation`; break;
                }

                // Baselining: no baseline at month 0, no credible movement to claim at month 6.
                spend = d.baseline / 1000; // GBP k -> GBP M
                if (d.baseline >= 80) { impactDelta += 8; }
                else if (d.baseline >= 40) { impactDelta += 3; }
                else { impactDelta -= 6; coachKey = `coach_r3_nobaseline`; }

                summaryKey = (d.levels === `behaviour_results` && d.metric === this.TRUE_METRIC && this.CREDIBLE_ATTRIBUTION.indexOf(d.attribution) >= 0) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Pitch & defend: honest, attribution-backed ROI beats a comforting headline (Error 5 + overpromise).
                switch (d.roi) {
                    case `attributed`: impactDelta += 12; diagDelta += 4; coachKey = `coach_r4_attributed`; break;
                    case `precise`: impactDelta -= 10; coachKey = `coach_r4_precise`; break;
                    case `none`: impactDelta -= 8; coachKey = `coach_r4_noroi`; break;
                }

                switch (d.boardCandour) {
                    case `honest`: diagDelta += 10; impactDelta += 4; coachKey = (d.roi === `attributed`) ? `coach_r4_honest` : coachKey; break;
                    case `overpromise`: diagDelta -= 6; impactDelta -= 10; ds.overpromised = true; coachKey = `coach_r4_overpromise`; break;
                    case `duck`: diagDelta -= 6; coachKey = `coach_r4_duck`; break;
                }

                switch (d.competitor) {
                    case `evidence`: impactDelta += 8; transferDelta += 4; break;
                    case `match`: impactDelta -= 12; ds.overpromised = true; coachKey = `coach_r4_match`; break;
                    case `discount`: transferDelta -= 8; diagDelta -= 4; coachKey = `coach_r4_discount`; break;
                }

                // Conviction nudges impact credibility.
                impactDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.roi === `attributed` && d.boardCandour === `honest` && d.competitor === `evidence`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Budget accounting (GBP millions, capped display at the ceiling + breach overflow shown honestly).
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 100) / 100;

            // Meters move on their deltas, bounded 0–100.
            ds.diag = Math.max(0, Math.min(100, ds.diag + diagDelta));
            ds.transfer = Math.max(0, Math.min(100, ds.transfer + transferDelta));
            ds.impact = Math.max(0, Math.min(100, ds.impact + impactDelta));

            ds.diagHistory.push(Math.round(ds.diag));
            ds.transferHistory.push(Math.round(ds.transfer));
            ds.impactHistory.push(Math.round(ds.impact));

            // v1.1.0: publish composite (0-100) to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            // Resolve the at-risk fee at the final round.
            if (round === this.ROUNDS.length) {
                const attributable = this.ATTRIBUTABLE_METRICS.indexOf(d.metric) >= 0
                    && this.CREDIBLE_ATTRIBUTION.indexOf(d.attribution) >= 0;
                if (!ds.budgetBreach && attributable && ds.impact >= this.IMPACT_FEE_FLOOR) {
                    ds.feeSecured = true; ds.feeLost = false;
                } else {
                    ds.feeSecured = false; ds.feeLost = true;
                }
            }

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                diag: Math.round(ds.diag),
                diagDelta: Math.round(diagDelta),
                transfer: Math.round(ds.transfer),
                transferDelta: Math.round(transferDelta),
                impact: Math.round(ds.impact),
                impactDelta: Math.round(impactDelta),
                budgetUsed: ds.budgetUsed,
                budgetBreach: ds.budgetBreach,
                feeSecured: ds.feeSecured,
                feeLost: ds.feeLost,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

