        // Composite (0-100) VERBATIM from v1.0.0 getPerformanceSummary; written to
        // domainState.performance.overallScore each period for the reporting/grading layer.
        _composite(ds) {
            var diag = Math.round(ds.diag || 0);
            var transfer = Math.round(ds.transfer || 0);
            var impact = Math.round(ds.impact || 0);
            return Math.round(diag * 0.34 + transfer * 0.33 + impact * 0.33);
        }

        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const diag = Math.round(ds.diag);
            const transfer = Math.round(ds.transfer);
            const impact = Math.round(ds.impact);

            const composite = this._composite(ds);
            const feeSecured = ds.feeSecured === true;
            const wellDiagnosed = diag >= 60;

            let performance = window.mySimulation.t(`perf_lost`);
            if (composite >= this.TARGET_COMPOSITE && feeSecured && wellDiagnosed) performance = window.mySimulation.t(`perf_award`);
            else if (composite >= this.TARGET_COMPOSITE && feeSecured) performance = window.mySimulation.t(`perf_credible`);
            else if (feeSecured) performance = window.mySimulation.t(`perf_feekept`);
            else if (ds.budgetBreach) performance = window.mySimulation.t(`perf_overbudget`);
            else if (composite >= 45) performance = window.mySimulation.t(`perf_short`);

            const insights = [];
            if (composite >= this.TARGET_COMPOSITE && feeSecured) insights.push(window.mySimulation.t(`insight_award`));
            else if (feeSecured) insights.push(window.mySimulation.t(`insight_feekept`));
            else if (ds.budgetBreach) insights.push(window.mySimulation.t(`insight_overbudget`));
            else insights.push(window.mySimulation.t(`insight_feelost`));

            if (diag < 45) insights.push(window.mySimulation.t(`insight_misdiagnosed`));
            if (transfer < 45) insights.push(window.mySimulation.t(`insight_notransfer`));
            if (impact < 45) insights.push(window.mySimulation.t(`insight_lowimpact`));
            if (ds.overpromised) insights.push(window.mySimulation.t(`insight_overpromised`));
            if (composite >= this.TARGET_COMPOSITE && feeSecured && transfer >= 55) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                diag: diag,
                transfer: transfer,
                impact: impact,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                feeSecured: feeSecured,
                budgetBreach: ds.budgetBreach,
                overpromised: ds.overpromised,
                budgetUsed: ds.budgetUsed,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || '';
            var ok = !!s.feeSecured;
            var badge = ok
                ? '<span class="programsim-cm-badge programsim-cm-yes">' + T('cm_met') + '</span>'
                : '<span class="programsim-cm-badge programsim-cm-no">' + T('cm_missed') + '</span>';
            var failBadge = (s.budgetBreach || s.overpromised)
                ? '<span class="programsim-cm-badge programsim-cm-warn">' + T('cm_failstate_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="programsim-cm-metric"><span class="programsim-cm-mv">' + Math.round(s.diag || 0) + '</span><span class="programsim-cm-ml">' + T('cm_m_diag') + '</span></div>'
                + '<div class="programsim-cm-metric"><span class="programsim-cm-mv">' + Math.round(s.transfer || 0) + '</span><span class="programsim-cm-ml">' + T('cm_m_transfer') + '</span></div>'
                + '<div class="programsim-cm-metric"><span class="programsim-cm-mv">' + Math.round(s.impact || 0) + '</span><span class="programsim-cm-ml">' + T('cm_m_impact') + '</span></div>';
            return ''
                + '<div class="programsim-completion">'
                +   '<div class="programsim-cm-head">'
                +     '<div class="programsim-cm-score">' + score + '<span class="programsim-cm-score-max">/100</span></div>'
                +     '<div class="programsim-cm-grade">' + grade + ' ' + badge + failBadge + '</div>'
                +   '</div>'
                +   '<div class="programsim-cm-metrics">' + metrics + '</div>'
                +   '<div class="programsim-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="programsim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

